  "text": "#let _auto-label-index = state(\"calepin-auto-label-index\", 1)\n#let _auto-inline-label-index = state(\"calepin-auto-inline-label-index\", 1)\n\n// The option vocabulary is defined once, in Rust (`typst/option_table.rs`),\n// and generated into this dictionary by `build.rs`. Do not hand-edit; add or\n// remove options in `OPTION_TABLE` instead.\n#let _base-options = (\n  script: true,\n  echo: true,\n  eval: true,\n  results: \"render\",\n  \"results-location\": \"statement\",\n  warning: true,\n  message: true,\n  error: false,\n  \"fig-device-format\": \"svg\",\n  \"fig-device-dpi\": 150,\n  \"fig-device-width\": 6,\n  \"fig-device-height\": auto,\n  \"fig-device-aspect\": 0.618,\n  \"fig-width\": 70%,\n  \"fig-height\": auto,\n  \"fig-align\": center,\n  \"fig-responsive\": true,\n  \"fig-link\": auto,\n  \"fig-caption\": none,\n  \"fig-cap-location\": auto,\n  \"fig-alt-text\": none,\n  \"fig-subcaptions\": none,\n  \"fig-layout-columns\": auto,\n  \"fig-layout-rows\": auto,\n  \"tbl-caption\": none,\n  \"lst-caption\": none,\n  kind: auto,\n  \"fenced-chunks\": true,\n)\n\n#let _setup-defaults = state(\"calepin-setup-defaults\", (default: _base-options))\n\n#let _call-extra-defaults = (\n  label: none,\n  inline-output: false,\n  store-get: none,\n  store-set: none,\n  auto-label-prefix: \"chunk\",\n  auto-label-state: _auto-label-index,\n)\n\n#let _auto-call-defaults(defaults) = {\n  let out = (:)\n  for key in defaults.keys() {\n    out.insert(key, auto)\n  }\n  out + _call-extra-defaults\n}\n\n#let _call-defaults = _auto-call-defaults(_base-options)\n"
